using sv_e4482c8ace974bda894334067a2b7721.Models;

namespace sv_e4482c8ace974bda894334067a2b7721.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_e4482c8ace974bda894334067a2b7721.Models;

namespace sv_e4482c8ace974bda894334067a2b7721.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomato sauce.", 30),
            new(2, "Pasta Carbonara", "Creamy Roman pasta with guanciale, egg yolk, Pecorino Romano, and black pepper.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa powder.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Tender marinated chicken in a rich, spiced tomato-cream sauce.", 50),
            new(5, "Palak Paneer", "Fresh spinach puree with cubes of soft paneer cheese and aromatic spices.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with spiced meat, caramelized onions, and saffron.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Sushi Rolls", "Vinegared rice with fresh fish and vegetables wrapped in nori seaweed.", 40),
            new(8, "Ramen", "Rich pork bone broth with wheat noodles, chashu pork, soft-boiled egg, and nori.", 120),
            new(9, "Tempura", "Lightly battered and deep-fried shrimp and seasonal vegetables.", 20),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_e4482c8ace974bda894334067a2b7721.Models
@using sv_e4482c8ace974bda894334067a2b7721.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

@if (_sortedRecipes is not null && _isRefreshing)
{
    <div class="alert alert-info py-1 px-2 d-inline-block" role="status">
        <span class="spinner-border spinner-border-sm me-1" aria-hidden="true"></span>
        Refreshing…
    </div>
}

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_sortedRecipes is null)
{
    <p role="status"><em>Loading recipes…</em></p>
}
else if (_sortedRecipes.Count == 0)
{
    <p>No recipes found for this cuisine.</p>
}
else
{
    <div class="row row-cols-1 row-cols-md-3 g-3">
        @foreach (var recipe in _sortedRecipes)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        Prep time: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Recipe>? _recipes;
    private List<Recipe>? _sortedRecipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    public override async Task SetParametersAsync(ParameterView parameters)
    {
        var previousCuisineId = CuisineId;

        await base.SetParametersAsync(parameters);

        if (CuisineId != previousCuisineId)
        {
            await LoadRecipesAsync();
        }
        else
        {
            ApplySort();
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        var cts = _loadCts;

        _error = null;
        _isRefreshing = _recipes is not null;
        StateHasChanged();

        try
        {
            var recipes = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
                return;

            _recipes = recipes;
            _loadedCuisineId = CuisineId;
            _isRefreshing = false;
            _error = null;
            ApplySort();
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Expected: user navigated away or changed cuisine; do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please check your connection and try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private void ApplySort()
    {
        if (_recipes is null)
        {
            _sortedRecipes = null;
            return;
        }

        _sortedRecipes = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? _recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : _recipes.OrderByDescending(r => r.Id).ToList(); // "newest" or default
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Dispose();
    }
}

